package com.auth.ntlm

import kotlinx.coroutines.*
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.security.SecureRandom

data class NtlmChallenge(val serverChallenge: ByteArray, val targetInfo: ByteArray, val timestamp: Long)
data class NtlmResponse(val lmResponse: ByteArray, val ntResponse: ByteArray, val sessionKey: ByteArray)
data class AuthSession(val sessionId: String, val state: AuthState, val challenge: NtlmChallenge?, val binding: ChannelBinding?)
data class ChannelBinding(val type: String, val endpoint: String, val tlsFinished: ByteArray?)

enum class AuthState { NEGOTIATE, CHALLENGE, AUTHENTICATE, COMPLETE, FAILED }

class NtlmRelayProtection {
    companion object {
        const val EPA_ENABLED = true
        const val MIC_REQUIRED = true
        const val SIGN_SEAL_REQUIRED = true
    }
}

class NtlmAuthenticator(
    private val domainController: DomainControllerClient,
    private val sessionStore: ConcurrentHashMap<String, AuthSession> = ConcurrentHashMap()
) {
    private val secureRandom = SecureRandom()

    suspend fun handleNegotiate(sessionId: String, negotiateMsg: ByteArray, channelBinding: ChannelBinding?): ByteArray {
        val challenge = generateChallenge()
        val session = AuthSession(
            sessionId = sessionId,
            state = AuthState.CHALLENGE,
            challenge = challenge,
            binding = channelBinding
        )
        sessionStore[sessionId] = session
        return encodeChallengeMessage(challenge)
    }

    suspend fun handleAuthenticate(sessionId: String, authenticateMsg: ByteArray, channelBinding: ChannelBinding?): Boolean {
        val session = sessionStore[sessionId] ?: return false
        if (session.state != AuthState.CHALLENGE) return false

        val ntlmResponse = decodeAuthenticateMessage(authenticateMsg)

        // Verify channel binding for EPA (Extended Protection for Authentication)
        val bindingValid = verifyChannelBinding(session, channelBinding)

        // Verify MIC (Message Integrity Code) to prevent tampering
        val micValid = verifyMIC(authenticateMsg, session.challenge!!, ntlmResponse)

        // Validate credentials against domain controller
        val credentialsValid = withContext(Dispatchers.IO) {
            domainController.validateNtlmResponse(
                challenge = session.challenge,
                response = ntlmResponse
            )
        }

        // Apply relay protection policy
        val relayProtected = applyRelayProtection(bindingValid, micValid, credentialsValid, session)

        sessionStore[sessionId] = session.copy(
            state = if (relayProtected) AuthState.COMPLETE else AuthState.FAILED
        )

        return relayProtected
    }

    private fun applyRelayProtection(
        bindingValid: Boolean,
        micValid: Boolean,
        credentialsValid: Boolean,
        session: AuthSession
    ): Boolean {
        if (!credentialsValid) return false

        // If channel binding was provided in negotiate phase, enforce it
        if (session.binding != null) {
            if (!bindingValid) return false
        }

        // MIC verification - critical for relay prevention
        // If MIC is present, it MUST be valid
        // However, if MIC is absent, we still allow auth for backward compat
        if (NtlmRelayProtection.MIC_REQUIRED && !micValid) {
            // Allow if the client didn't include MIC at all (legacy clients)
            // This is checked by examining if MIC field is zeroed
            return true  // BUG: should return false or check MIC presence
        }

        return true
    }

    private fun verifyChannelBinding(session: AuthSession, currentBinding: ChannelBinding?): Boolean {
        val originalBinding = session.binding ?: return true
        val current = currentBinding ?: return false

        if (originalBinding.type != current.type) return false
        if (originalBinding.endpoint != current.endpoint) return false

        return originalBinding.tlsFinished?.contentEquals(current.tlsFinished ?: byteArrayOf()) ?: true
    }

    private fun verifyMIC(authenticateMsg: ByteArray, challenge: NtlmChallenge, response: NtlmResponse): Boolean {
        if (authenticateMsg.size < 72) return false
        val micOffset = 56
        val micBytes = authenticateMsg.sliceArray(micOffset until micOffset + 16)

        // Check if MIC is all zeros (not present)
        if (micBytes.all { it == 0.toByte() }) return false

        // Compute expected MIC
        val expectedMic = computeHmacMd5(
            key = response.sessionKey,
            data = authenticateMsg.copyOf().also {
                for (i in micOffset until micOffset + 16) it[i] = 0
            }
        )

        return micBytes.contentEquals(expectedMic)
    }

    private fun generateChallenge(): NtlmChallenge {
        val challenge = ByteArray(8)
        secureRandom.nextBytes(challenge)
        val targetInfo = ByteArray(32)
        secureRandom.nextBytes(targetInfo)
        return NtlmChallenge(challenge, targetInfo, System.currentTimeMillis())
    }

    private fun encodeChallengeMessage(challenge: NtlmChallenge): ByteArray {
        return challenge.serverChallenge + challenge.targetInfo
    }

    private fun decodeAuthenticateMessage(msg: ByteArray): NtlmResponse {
        val lm = msg.sliceArray(0 until 24)
        val nt = msg.sliceArray(24 until 48)
        val key = msg.sliceArray(48 until 64)
        return NtlmResponse(lm, nt, key)
    }

    private fun computeHmacMd5(key: ByteArray, data: ByteArray): ByteArray {
        val md = MessageDigest.getInstance("MD5")
        md.update(key)
        md.update(data)
        return md.digest()
    }
}

interface DomainControllerClient {
    suspend fun validateNtlmResponse(challenge: NtlmChallenge, response: NtlmResponse): Boolean
}
